$css = '<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"><title>PLACEHOLDER</title><meta name="description" content="PLACEHOLDER"><style>@import url("https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800;900&display=swap");*{margin:0;padding:0;box-sizing:border-box}:root{--bg:#09090b;--bg-card:#111113;--border:rgba(255,255,255,.06);--text:#fafafa;--text-sec:#a1a1aa;--text-muted:#52525b;--purple:#a78bfa;--emerald:#34d399;--red:#ef4444;--radius:12px}body{font-family:Inter,sans-serif;background:var(--bg);color:var(--text)}a{color:var(--purple);text-decoration:none}.nav{position:sticky;top:0;z-index:100;padding:14px 24px;background:rgba(9,9,11,.85);backdrop-filter:blur(16px);border-bottom:1px solid var(--border)}.nav-inner{max-width:900px;margin:0 auto;display:flex;align-items:center;justify-content:space-between}.brand-text{font-weight:800;background:linear-gradient(135deg,#6366f1,var(--emerald));-webkit-background-clip:text;-webkit-text-fill-color:transparent}.nav-links a{padding:7px 14px;border-radius:100px;font-size:.82em;color:#a1a1aa}.container{max-width:900px;margin:0 auto;padding:24px}.lesson-body h2{font-size:1.5em;font-weight:900;margin:32px 0 12px}.lesson-body p{color:var(--text-sec);font-size:.92em;line-height:1.7;margin-bottom:12px}.btn{padding:8px 20px;border-radius:100px;font-weight:600;font-size:.82em;border:none;cursor:pointer}.btn-primary{background:rgba(167,139,250,.15);color:var(--purple)}.btn-success{background:rgba(52,211,153,.15);color:var(--emerald)}.story-card{background:linear-gradient(135deg,rgba(96,165,250,.06),rgba(167,139,250,.04));border:1px solid rgba(167,139,250,.15);border-radius:var(--radius);padding:20px;margin-bottom:20px;position:relative;overflow:hidden}.story-label{font-size:.72em;font-weight:600;text-transform:uppercase;letter-spacing:1.2px;color:var(--purple);margin-bottom:3px}.story-title{font-size:1.05em;font-weight:700;margin-bottom:8px;line-height:1.4;color:var(--text)}.story-text{font-size:.85em;line-height:1.7;color:var(--text-sec);margin-bottom:12px}.story-moral{font-size:.82em;font-style:italic;color:var(--emerald);padding:10px 14px;background:rgba(52,211,153,.06);border-radius:8px;border-left:3px solid var(--emerald)}.section-label{display:inline-block;font-size:.72em;font-weight:700;text-transform:uppercase;letter-spacing:1.5px;padding:4px 14px;border-radius:100px;margin:28px 0 4px}.part1{color:#60a5fa;background:rgba(96,165,250,.1)}.part2{color:var(--purple);background:rgba(167,139,250,.1)}.part3{color:var(--emerald);background:rgba(52,211,153,.1)}.part4{color:#f97316;background:rgba(249,115,22,.1)}.section-divider{height:1px;background:var(--border);margin:32px 0}.quote-box{background:linear-gradient(135deg,rgba(167,139,250,.08),rgba(52,211,153,.04));border:1px solid rgba(167,139,250,.15);border-radius:var(--radius);padding:20px;margin-bottom:20px}.quote{font-size:1em;font-weight:500;font-style:italic;color:var(--text);margin-bottom:6px}.attribution{font-size:.82em;color:var(--text-muted)}.q-card{background:var(--bg-card);border:1px solid var(--border);border-radius:var(--radius);padding:20px;margin-bottom:16px}.q-text{font-weight:600;font-size:.92em;margin-bottom:12px;line-height:1.5}.q-opts{display:flex;flex-direction:column;gap:8px}.q-opt{padding:10px 14px;border-radius:8px;border:1px solid var(--border);cursor:pointer;font-size:.85em;color:var(--text-sec);transition:all .2s}.q-opt:hover{background:rgba(167,139,250,.08);border-color:rgba(167,139,250,.3)}.q-opt.correct{background:rgba(52,211,153,.15);border-color:var(--emerald);color:var(--emerald)}.q-opt.wrong{background:rgba(239,68,68,.15);border-color:var(--red);color:var(--red)}.q-opt.disabled{pointer-events:none;opacity:.6}.q-soln{display:none;margin-top:12px;padding:12px;background:rgba(167,139,250,.06);border-radius:8px;font-size:.82em;color:var(--text-sec);line-height:1.6}.q-opt.correct~.q-soln,.q-opt.wrong~.q-soln{display:block}.q-soln.show{display:block}</style></head><body><nav class="nav"><div class="nav-inner"><a href="index.html"><span class="brand-text">vlymbooq</span></a><div class="nav-links"><a href="index.html">Home</a><a href="math.html">Math Map</a><a href="physics.html">Physics Map</a><a href="chemistry.html">Chemistry</a></div></div></nav><div class="container"><div class="lesson-body">'

$footer = '</div></div><script>var practiceQs=QUESTIONS;var answered={},correctCount=0;function renderPractice(){var c=document.getElementById("practice-qs"),h="";for(var i=0;i<practiceQs.length;i++){var q=practiceQs[i],o="";for(var j=0;j<q.opts.length;j++){o+="<div class=\\"q-opt\\" onclick=\\"selectOpt("+q.id+","+j+")\\">"+q.opts[j].l+". "+q.opts[j].t+"</div>";}h+="<div class=\\"q-card\\" id=\\"q-"+q.id+"\\"><div class=\\"q-text\\">"+(i+1)+". "+q.text+"</div><div class=\\"q-opts\\">"+o+"</div><div class=\\"q-soln\\" id=\\"soln-"+q.id+"\\"><strong>"+getCorrectLabel(q)+"</strong><br>"+q.sol+"</div></div>";}c.innerHTML=h;}function getCorrectLabel(q){for(var i=0;i<q.opts.length;i++){if(q.opts[i].c)return q.opts[i].l+". "+q.opts[i].t;}return "";}function selectOpt(qId,idx){if(answered[qId])return;answered[qId]=true;var q=practiceQs.filter(function(x){return x.id===qId})[0];var opts=document.querySelectorAll("#q-"+qId+" .q-opt"),isCorrect=q.opts[idx].c;for(var i=0;i<opts.length;i++)opts[i].classList.add("disabled");if(isCorrect){opts[idx].classList.add("correct");correctCount++;}else{opts[idx].classList.add("wrong");for(var i=0;i<q.opts.length;i++){if(q.opts[i].c)opts[i].classList.add("correct");}}document.getElementById("soln-"+qId).classList.add("show");}function resetPractice(){if(!confirm("Reset?"))return;answered={};correctCount=0;document.querySelectorAll(".q-opt").forEach(function(e){e.className="q-opt"});document.querySelectorAll(".q-soln").forEach(function(e){e.classList.remove("show")});renderPractice();}renderPractice();</script></body></html>'

$dir = "C:\Users\Renjith\Desktop\icode (2)\study"

function Write-Lesson {
    param($file, $title, $desc, $h2, $p, $quote, $attribution, $parts, $qs)
    
    $html = $css.Replace("PLACEHOLDER", $title)
    $html = $html.Replace("PLACEHOLDER", $desc)
    
    $html += $h2
    $html += $p
    $html += '<div class="quote-box"><div class="quote">' + $quote + '</div><div class="attribution">' + $attribution + '</div></div>'
    
    foreach ($part in $parts) {
        $html += '<div class="section-label part' + $part[0] + '">Part ' + $part[0] + '</div>'
        $html += '<h2>' + $part[1] + '</h2>'
        $html += '<div class="story-card"><div class="story-label">' + $part[2] + '</div><div class="story-title">' + $part[3] + '</div><div class="story-text">' + $part[4] + '</div><div class="story-moral">' + $part[5] + '</div></div>'
    }
    
    $html += '<div class="section-divider"></div><h2 style="margin-top:0">🎯 Practice</h2><div id="practice-qs"></div><div style="margin-top:16px"><button class="btn btn-primary" onclick="resetPractice()">🔄 Reset All</button><a href="chemistry.html" class="btn btn-success">← Back to Chemistry</a></div>'
    
    $json = $qs | ConvertTo-Json -Compress -Depth 10
    $html += $footer.Replace("QUESTIONS", $json)
    
    [System.IO.File]::WriteAllText($file, $html, [System.Text.Encoding]::UTF8)
    Write-Host "Created: $file"
}

